import sys

def longest_palindromic_prefix(s):
    n = len(s)
    rev_s = s[::-1]
    combined = s + "#" + rev_s
    lps = [0] * len(combined)
    for i in range(1, len(combined)):
        j = lps[i - 1]
        while j > 0 and combined[i] != combined[j]:
            j = lps[j - 1]
        if combined[i] == combined[j]:
            j += 1
        lps[i] = j
    return s[:lps[-1]]

def longest_palindromic_suffix(s):
    return longest_palindromic_prefix(s[::-1])[::-1]

def count_prefix_frequencies(s):
    freq = {}
    for i in range(len(s)):
        prefix = s[:i+1]
        if prefix in freq:
            freq[prefix] += 1
        else:
            freq[prefix] = 1
    return [freq[s[:i+1]] for i in range(len(s))]

def main():
    import sys
    s = sys.stdin.read().strip()
    longest_prefix = longest_palindromic_prefix(s)
    longest_suffix = longest_palindromic_suffix(s)
    omeric_string = longest_suffix + longest_prefix
    print(omerics_string)
    print(' '.join(map(str, count_prefix_frequencies(omerics_string))))

if __name__ == "__main__":
    main()
